using MailKit.Net.Smtp;
using MimeKit;

public async Task SendAsync()
{
    var message = new MimeMessage();
    message.From.Add(new MailboxAddress("MyApp", "noreply@myapp.com"));
    message.To.Add(new MailboxAddress("User", "user@example.com"));
    message.Subject = "Account Created";

    message.Body = new TextPart("plain")
    {
        Text = "Your account has been created successfully."
    };

    using var client = new SmtpClient();
    await client.ConnectAsync("smtp.example.com", 587, MailKit.Security.SecureSocketOptions.StartTls);
    await client.AuthenticateAsync("user", "password");
    await client.SendAsync(message);
    await client.DisconnectAsync(true);
}

using MailKit.Net.Imap;
using MailKit.SearchSorter;

public async Task ListRecentAsync()
{
    using var client = new ImapClient();
    await client.ConnectAsync("imap.example.com", 993, true);
    await client.AuthenticateAsync("user", "password");

    var inbox = client.Inbox;
    await inbox.OpenAsync(MailKit.FolderAccess.ReadOnly);

    var uids = await inbox.SearchAsync(MailKit.Search.SearchQuery.Recent);
    foreach (var uid in uids)
    {
        var message = await inbox.GetMessageAsync(uid);
        Console.WriteLine($"{uid}: {message.Subject}");
    }

    await client.DisconnectAsync(true);
}
